let packingDrafts={},batchSequence=0;
function draftFor(n){return packingDrafts[n]??=[]}
function stageRow(n,poolId){const p=boxes.find(b=>b.id===poolId&&b.awaitingPacking);if(!p)return;const rows=draftFor(n),used=rows.filter(r=>r.poolId===poolId).reduce((s,r)=>s+Number(r.qty||0),0);rows.push({poolId,boxId:'',qty:Math.min(100,Math.max(0,p.qty-used)),loc:p.suggestedDestination});packingPage(n)}
function editStage(n,i,key,value){draftFor(n)[i][key]=value;updateBatchTotals(n)}
function updateBatchTotals(n){const rows=draftFor(n);for(const p of boxes.filter(b=>b.awaitingPacking&&b.inspectionIndex===n)){const staged=rows.filter(r=>r.poolId===p.id).reduce((s,r)=>s+(Number(r.qty)||0),0),e=$('remaining-'+p.id);if(e)e.textContent=`${p.qty} a encaixotar · ${staged} neste lote · ${p.qty-staged} restantes`}}
function validatePackBatch(n,rows){if(!rows.length)throw Error('Adicione pelo menos uma caixa.');const used=new Set(),totals={};for(const r of rows){const p=boxes.find(b=>b.id===r.poolId&&b.awaitingPacking&&b.inspectionIndex===n),id=assetIdKey(r.boxId),qty=Number(r.qty),loc=Number(r.loc);if(!p||p.qty<=0)throw Error('Classificação sem saldo.');if(!mediumAssets.some(a=>a.id===id))throw Error('Caixa média não cadastrada: '+id);if(used.has(id))throw Error('Caixa repetida no lote: '+id);used.add(id);if(packedContents(id))throw Error('Caixa ocupada: '+id);if(!Number.isInteger(qty)||qty<1||qty>100)throw Error('Cada caixa deve ter entre 1 e 100 pops.');if(!Number.isInteger(loc)||loc<0||loc>=locations.length)throw Error('Destino inválido.');totals[p.id]=(totals[p.id]||0)+qty;if(totals[p.id]>p.qty)throw Error('Quantidade excede o saldo de '+p.grade+'.')}return true}
function commitPackBatch(n,rows){validatePackBatch(n,rows);const batchId='PACK-'+String(++batchSequence).padStart(3,'0'),fills=rows.map(r=>commitPack(r.poolId,r.boxId,r.qty,r.loc));for(const f of fills){f.batchId=batchId;const h=fillHistory.find(h=>h.fillId===f.fillId),saved=inspections[n].fills.find(h=>h.fillId===f.fillId);h.batchId=batchId;saved.batchId=batchId}packingDrafts[n]=[];log(`${batchId}: ${fills.length} caixas confirmadas, ${fills.reduce((s,f)=>s+f.qty,0)} pops.`);return fills}
function savePackBatch(e,n){e.preventDefault();try{commitPackBatch(n,draftFor(n));packingPage(n);toast('Lote de caixas confirmado')}catch(err){$('packing-error').textContent=err.message}}
packingPage=function(n){const r=inspections[n],pools=boxes.filter(b=>b.awaitingPacking&&b.inspectionIndex===n&&b.qty>0),rows=draftFor(n);go('Encaixotamento');$('app').innerHTML=`<div class="heading"><div><h1>Encaixotamento em lote</h1><p>${esc(r.name)} · ${esc(r.lot)} · ${esc(r.receiptId||'Exemplo inicial')}</p></div><button onclick="go('Conferência')">Voltar</button></div><div class="notice">Encha as caixas fisicamente, escaneie os IDs e confirme o conjunto. Nenhum saldo muda até confirmar o lote. Pode salvar parte e continuar depois nesta sessão.</div><section class="panel"><h2>${packingRemainder(n)} pops ainda sem caixa</h2><p>${r.fills.length} enchimentos confirmados. Mesmo sabor, lote e classe em cada caixa.</p></section><form onsubmit="savePackBatch(event,${n})"><div class="grade-grid">${pools.map(p=>`<section class="panel"><h2>${p.grade}</h2><p id="remaining-${p.id}"></p><button type="button" onclick="stageRow(${n},'${p.id}')">＋ Caixa ${p.grade}</button></section>`).join('')}</div>${rows.map((row,i)=>{const p=boxes.find(b=>b.id===row.poolId);return `<section class="panel"><div class="row"><strong>Caixa ${i+1} · ${p.grade}</strong><button type="button" onclick="draftFor(${n}).splice(${i},1);packingPage(${n})">Remover</button></div><div class="receipt-grid"><label>Escanear ID permanente<input list="empty-medium" value="${esc(row.boxId)}" required placeholder="MEDIA-001" oninput="editStage(${n},${i},'boxId',this.value)" onkeydown="if(event.key==='Enter'){event.preventDefault();$('batch-qty-${i}').focus()}"></label><label>Quantidade<input id="batch-qty-${i}" type="number" min="1" max="100" step="1" value="${row.qty}" required oninput="editStage(${n},${i},'qty',this.value)"></label><label>Destino<select onchange="editStage(${n},${i},'loc',this.value)">${opts(locations,Number(row.loc))}</select></label></div></section>`}).join('')}<datalist id="empty-medium">${mediumAssets.filter(a=>!packedContents(a.id)).map(a=>`<option value="${a.id}">${esc(a.name)}</option>`).join('')}</datalist><p id="packing-error" role="alert" class="receipt-error"></p>${rows.length?'<button type="submit" class="primary">Confirmar lote de caixas</button>':''}</form><section class="panel"><h2>Caixas já vinculadas</h2>${r.fills.map(f=>`<div class="row"><div><strong>${f.boxId} · ${f.qty} pops · ${f.grade}</strong><small>${f.batchId||''} · ${f.fillId} · ${esc(f.lot)}</small></div><button onclick="mediumHistory('${f.boxId}')">Histórico</button></div>`).join('')||'<p>Adicione as caixas preenchidas acima.</p>'}<div class="actions">${r.fills.length?`<button onclick="showLabels(${n})">Imprimir etiquetas juntas</button>`:''}<button onclick="go('Cadastros')">Cadastrar caixas</button><button onclick="go('Inventário')">Inventário</button></div></section>`;updateBatchTotals(n)};
